-- ENJAZ Phase 9.3 / M2 — Real Cloud full-governance destruction probe v2
-- No Auth rows are created. The anon boundary is tested through auth.uid() with service execution,
-- so the probe never grants schema private usage to anon. All fixtures and helpers are removed.
begin;

create or replace function private.enjaz_p93m2_assert(ok boolean,msg text) returns void language plpgsql security invoker set search_path='' as $$begin if not coalesce(ok,false) then raise exception 'ENJAZ_P93M2_PROBE: %',msg; end if; end$$;
create or replace function private.enjaz_p93m2_direct_capital_denied(ws uuid,co uuid) returns boolean language plpgsql security invoker set search_path='' as $$begin update public.companies set capital=999 where workspace_id=ws and id=co; return false; exception when insufficient_privilege then return sqlerrm='ENJAZ_CAPITAL_REQUIRES_GOVERNANCE_COMMAND'; end$$;
create or replace function private.enjaz_p93m2_owner_required(ws uuid,co uuid,person uuid) returns boolean language plpgsql security invoker set search_path='' as $$begin perform public.replace_company_beneficial_owners_v1(ws,co,1,gen_random_uuid(),date '2026-04-01',jsonb_build_array(jsonb_build_object('contactId',person,'basis','ownership','percentage','100'))); return false; exception when insufficient_privilege then return sqlerrm='ENJAZ_ORG_OWNER_REQUIRED'; end$$;
create or replace function private.enjaz_p93m2_read_denied(ws uuid,co uuid,expected text) returns boolean language plpgsql security invoker set search_path='' as $$begin perform public.get_company_governance_context_v1(ws,co,date '2026-02-01'); return false; exception when insufficient_privilege then return sqlerrm=expected; end$$;
create or replace function private.enjaz_p93m2_cross_denied(ws uuid,co uuid,person uuid) returns boolean language plpgsql security invoker set search_path='' as $$begin perform public.replace_company_beneficial_owners_v1(ws,co,1,gen_random_uuid(),date '2026-04-01',jsonb_build_array(jsonb_build_object('contactId',person,'basis','ownership','percentage','100'))); return false; exception when no_data_found then return sqlerrm='ENJAZ_BENEFICIAL_OWNER_CONTACT_NOT_FOUND'; end$$;
create or replace function private.enjaz_p93m2_resolution_stale(ws uuid,co uuid) returns boolean language plpgsql security invoker set search_path='' as $$begin perform public.record_company_resolution_v1(ws,co,0,gen_random_uuid(),'M2-STALE','Stale','general',date '2026-03-01',null); return false; exception when serialization_failure then return sqlerrm='ENJAZ_RESOLUTION_STALE'; end$$;
revoke all on function private.enjaz_p93m2_assert(boolean,text) from public,anon,authenticated;
revoke all on function private.enjaz_p93m2_direct_capital_denied(uuid,uuid) from public,anon;
revoke all on function private.enjaz_p93m2_owner_required(uuid,uuid,uuid) from public,anon;
revoke all on function private.enjaz_p93m2_read_denied(uuid,uuid,text) from public,anon;
revoke all on function private.enjaz_p93m2_cross_denied(uuid,uuid,uuid) from public,anon;
revoke all on function private.enjaz_p93m2_resolution_stale(uuid,uuid) from public,anon;
grant execute on function private.enjaz_p93m2_assert(boolean,text),private.enjaz_p93m2_direct_capital_denied(uuid,uuid),private.enjaz_p93m2_owner_required(uuid,uuid,uuid),private.enjaz_p93m2_read_denied(uuid,uuid,text),private.enjaz_p93m2_cross_denied(uuid,uuid,uuid),private.enjaz_p93m2_resolution_stale(uuid,uuid) to authenticated;

select set_config('p93.owner',(select w.owner_user_id::text from public.workspaces w join public.workspace_memberships m on m.workspace_id=w.id and m.user_id=w.owner_user_id and m.role='owner' order by w.created_at limit 1),true);
select private.enjaz_p93m2_assert(nullif(current_setting('p93.owner',true),'') is not null,'owner missing');
select set_config('p93.ws',(select id::text from public.workspaces where owner_user_id=current_setting('p93.owner')::uuid order by created_at limit 1),true);
select private.enjaz_p93m2_assert(not exists(select 1 from public.workspaces where id='93f00000-0000-4000-8000-000000000002'::uuid) and not exists(select 1 from public.companies where id='93f00000-0000-4000-8000-000000000010'::uuid),'pre-existing probe residue');
insert into public.workspaces(id,owner_user_id,name) values('93f00000-0000-4000-8000-000000000002',current_setting('p93.owner')::uuid,'__P93_M2_FOREIGN__');
insert into public.companies(id,workspace_id,legal_name,display_name,status) values('93f00000-0000-4000-8000-000000000010',current_setting('p93.ws')::uuid,'__P93_M2_COMPANY__','P93 M2 Company','active');
insert into public.contacts(id,workspace_id,display_name,contact_type,status) values
('93f00000-0000-4000-8000-000000000011',current_setting('p93.ws')::uuid,'P93 Beneficial','client','active'),
('93f00000-0000-4000-8000-000000000012',current_setting('p93.ws')::uuid,'P93 Manager','client','active'),
('93f00000-0000-4000-8000-000000000013','93f00000-0000-4000-8000-000000000002','P93 Foreign','client','active');

select set_config('request.jwt.claims',jsonb_build_object('role','authenticated','sub',current_setting('p93.owner'))::text,true); select set_config('request.jwt.claim.sub',current_setting('p93.owner'),true); set local role authenticated;
select private.enjaz_p93m2_assert(auth.uid()=current_setting('p93.owner')::uuid,'owner JWT');
select private.enjaz_p93m2_assert(has_table_privilege('public.corporate_beneficial_owners','SELECT') and not has_table_privilege('public.corporate_beneficial_owners','INSERT') and has_table_privilege('public.corporate_authority_grants','SELECT') and not has_table_privilege('public.corporate_authority_grants','UPDATE') and has_table_privilege('public.corporate_resolutions','SELECT') and not has_table_privilege('public.corporate_resolutions','DELETE') and has_table_privilege('public.corporate_capital_events','SELECT') and not has_table_privilege('public.corporate_capital_events','INSERT'),'governance tables not SELECT-only');
with x as (select public.replace_company_ownership_snapshot_v1(current_setting('p93.ws')::uuid,'93f00000-0000-4000-8000-000000000010',0,gen_random_uuid(),date '2026-01-01',jsonb_build_array(jsonb_build_object('kind','person','id','93f00000-0000-4000-8000-000000000011','role','shareholder','percentage','100'))) b) select private.enjaz_p93m2_assert((b->>'version')::int=1,'ownership') from x;
select set_config('p93.bop',gen_random_uuid()::text,true);
with x as (select public.replace_company_beneficial_owners_v1(current_setting('p93.ws')::uuid,'93f00000-0000-4000-8000-000000000010',0,current_setting('p93.bop')::uuid,date '2026-01-01',jsonb_build_array(jsonb_build_object('contactId','93f00000-0000-4000-8000-000000000011','basis','ownership','percentage','100'))) b) select private.enjaz_p93m2_assert((b->>'version')::int=1 and b->>'replayed'='false','beneficial') from x;
with x as (select public.replace_company_beneficial_owners_v1(current_setting('p93.ws')::uuid,'93f00000-0000-4000-8000-000000000010',0,current_setting('p93.bop')::uuid,date '2026-01-01',jsonb_build_array(jsonb_build_object('contactId','93f00000-0000-4000-8000-000000000011','basis','ownership','percentage','100'))) b) select private.enjaz_p93m2_assert(b->>'replayed'='true','beneficial replay') from x;
select set_config('p93.grant',(public.grant_company_authority_v1(current_setting('p93.ws')::uuid,'93f00000-0000-4000-8000-000000000010',0,gen_random_uuid(),'93f00000-0000-4000-8000-000000000012','manager','full',jsonb_build_array('sign','represent'),date '2026-01-15',date '2026-12-31')->>'grantId'),true);
with x as (select public.record_company_resolution_v1(current_setting('p93.ws')::uuid,'93f00000-0000-4000-8000-000000000010',0,gen_random_uuid(),'M2-001','تعيين المدير المفوض','appointment',date '2026-01-15','probe') b) select private.enjaz_p93m2_assert((b->>'version')::int=1,'resolution') from x;
with x as (select public.record_company_capital_event_v1(current_setting('p93.ws')::uuid,'93f00000-0000-4000-8000-000000000010',0,gen_random_uuid(),'set','1000000',date '2026-01-20','probe') b) select private.enjaz_p93m2_assert((b->>'version')::int=1 and b->>'capital'='1000000','capital') from x;
select private.enjaz_p93m2_assert(private.enjaz_p93m2_direct_capital_denied(current_setting('p93.ws')::uuid,'93f00000-0000-4000-8000-000000000010'),'capital bypass');
select private.enjaz_p93m2_assert(private.enjaz_p93m2_resolution_stale(current_setting('p93.ws')::uuid,'93f00000-0000-4000-8000-000000000010'),'stale resolution');
select private.enjaz_p93m2_assert(private.enjaz_p93m2_cross_denied(current_setting('p93.ws')::uuid,'93f00000-0000-4000-8000-000000000010','93f00000-0000-4000-8000-000000000013'),'cross workspace');
with x as (select public.get_company_governance_context_v1(current_setting('p93.ws')::uuid,'93f00000-0000-4000-8000-000000000010',date '2026-02-01') b) select private.enjaz_p93m2_assert(b->>'schema'='enjaz.governance-context.v1' and b->>'canMutate'='true' and (b#>>'{versions,ownership}')::int=1 and (b#>>'{versions,beneficialOwners}')::int=1 and (b#>>'{versions,authority}')::int=1 and (b#>>'{versions,resolutions}')::int=1 and (b#>>'{versions,capital}')::int=1 and jsonb_array_length(b->'beneficialOwners')=1 and jsonb_array_length(b->'authorities')=1 and b#>>'{capital,amount}'='1000000','unified context') from x;

select set_config('request.jwt.claims',jsonb_build_object('role','authenticated','sub','93f00000-0000-4000-8000-000000000099')::text,true); select set_config('request.jwt.claim.sub','93f00000-0000-4000-8000-000000000099',true);
select private.enjaz_p93m2_assert(private.enjaz_p93m2_owner_required(current_setting('p93.ws')::uuid,'93f00000-0000-4000-8000-000000000010','93f00000-0000-4000-8000-000000000011'),'non-owner mutation');
select private.enjaz_p93m2_assert(private.enjaz_p93m2_read_denied(current_setting('p93.ws')::uuid,'93f00000-0000-4000-8000-000000000010','ENJAZ_ORG_WORKSPACE_FORBIDDEN'),'foreign read');
reset role;
-- Anonymous auth boundary: auth.uid() is null. Keep service execution so no private-schema privilege is widened for anon.
select set_config('request.jwt.claims',jsonb_build_object('role','anon')::text,true); select set_config('request.jwt.claim.sub','',true);
select private.enjaz_p93m2_assert(private.enjaz_p93m2_read_denied(current_setting('p93.ws')::uuid,'93f00000-0000-4000-8000-000000000010','ENJAZ_ORG_AUTH_REQUIRED'),'anon read');
select set_config('request.jwt.claims',jsonb_build_object('role','authenticated','sub',current_setting('p93.owner'))::text,true); select set_config('request.jwt.claim.sub',current_setting('p93.owner'),true); set local role authenticated;
with x as (select public.replace_company_beneficial_owners_v1(current_setting('p93.ws')::uuid,'93f00000-0000-4000-8000-000000000010',1,gen_random_uuid(),date '2026-07-01','[]'::jsonb) b) select private.enjaz_p93m2_assert((b->>'version')::int=2,'beneficial close') from x;
with x as (select public.revoke_company_authority_v1(current_setting('p93.ws')::uuid,'93f00000-0000-4000-8000-000000000010',1,gen_random_uuid(),current_setting('p93.grant')::uuid,date '2026-08-01','probe revoke') b) select private.enjaz_p93m2_assert((b->>'version')::int=2,'authority revoke') from x;
with x as (select public.record_company_capital_event_v1(current_setting('p93.ws')::uuid,'93f00000-0000-4000-8000-000000000010',1,gen_random_uuid(),'increase','2000000',date '2026-08-05','probe increase') b) select private.enjaz_p93m2_assert((b->>'version')::int=2 and b->>'capital'='2000000','capital increase') from x;
with old_ctx as (select public.get_company_governance_context_v1(current_setting('p93.ws')::uuid,'93f00000-0000-4000-8000-000000000010',date '2026-02-01') b), new_ctx as (select public.get_company_governance_context_v1(current_setting('p93.ws')::uuid,'93f00000-0000-4000-8000-000000000010',date '2026-09-01') b) select private.enjaz_p93m2_assert(jsonb_array_length(old_ctx.b->'beneficialOwners')=1 and jsonb_array_length(old_ctx.b->'authorities')=1 and old_ctx.b#>>'{capital,amount}'='1000000' and jsonb_array_length(new_ctx.b->'beneficialOwners')=0 and jsonb_array_length(new_ctx.b->'authorities')=0 and new_ctx.b#>>'{capital,amount}'='2000000' and exists(select 1 from jsonb_array_elements(new_ctx.b->'risks') r where r->>'code'='BENEFICIAL_OWNER_MISSING') and exists(select 1 from jsonb_array_elements(new_ctx.b->'risks') r where r->>'code'='REPRESENTATION_AUTHORITY_MISSING'),'historical context') from old_ctx,new_ctx;
reset role;

delete from public.audit_events where entity_id='93f00000-0000-4000-8000-000000000010';
delete from public.corporate_capital_events where company_id='93f00000-0000-4000-8000-000000000010'; delete from public.corporate_resolutions where company_id='93f00000-0000-4000-8000-000000000010'; delete from public.corporate_authority_grants where company_id='93f00000-0000-4000-8000-000000000010'; delete from public.corporate_beneficial_owners where company_id='93f00000-0000-4000-8000-000000000010'; delete from public.corporate_ownership_stakes where company_id='93f00000-0000-4000-8000-000000000010'; delete from public.corporate_governance_events where company_id='93f00000-0000-4000-8000-000000000010'; delete from public.corporate_registry_states where company_id='93f00000-0000-4000-8000-000000000010'; delete from public.corporate_ownership_states where company_id='93f00000-0000-4000-8000-000000000010'; delete from public.companies where id='93f00000-0000-4000-8000-000000000010'; delete from public.contacts where id in ('93f00000-0000-4000-8000-000000000011','93f00000-0000-4000-8000-000000000012','93f00000-0000-4000-8000-000000000013'); delete from public.workspaces where id='93f00000-0000-4000-8000-000000000002';
select private.enjaz_p93m2_assert(not exists(select 1 from public.workspaces where id='93f00000-0000-4000-8000-000000000002') and not exists(select 1 from public.companies where id='93f00000-0000-4000-8000-000000000010') and not exists(select 1 from public.contacts where id in ('93f00000-0000-4000-8000-000000000011','93f00000-0000-4000-8000-000000000012','93f00000-0000-4000-8000-000000000013')) and not exists(select 1 from public.corporate_governance_events where company_id='93f00000-0000-4000-8000-000000000010'),'zero residue');
drop function private.enjaz_p93m2_resolution_stale(uuid,uuid); drop function private.enjaz_p93m2_cross_denied(uuid,uuid,uuid); drop function private.enjaz_p93m2_read_denied(uuid,uuid,text); drop function private.enjaz_p93m2_owner_required(uuid,uuid,uuid); drop function private.enjaz_p93m2_direct_capital_denied(uuid,uuid); drop function private.enjaz_p93m2_assert(boolean,text);
commit;
